macro_rules! deps {
    () => {
        TraitCannotImplForTy!();
        ImplForTyRequires!();
    };
}

macro_rules! infringing_fields_error {
    () => {
        deps!();
        fn infringing_fields_error < 'tcx > (tcx : TyCtxt < 'tcx > , infringing_tys : impl Iterator < Item = (Span , Ty < 'tcx > , InfringingFieldsReason < 'tcx >) > , lang_item : LangItem , impl_did : LocalDefId , impl_span : Span ,) -> ErrorGuaranteed { let trait_did = tcx . require_lang_item (lang_item , impl_span) ; let trait_name = tcx . def_path_str (trait_did) ; let mut errors : BTreeMap < _ , Vec < _ > > = Default :: default () ; let mut bounds = vec ! [] ; let mut seen_tys = FxHashSet :: default () ; let mut label_spans = Vec :: new () ; for (span , ty , reason) in infringing_tys { if ! seen_tys . insert (ty) { continue ; } label_spans . push (span) ; match reason { InfringingFieldsReason :: Fulfill (fulfillment_errors) => { for error in fulfillment_errors { let error_predicate = error . obligation . predicate ; if error_predicate != error . root_obligation . predicate { errors . entry ((ty . to_string () , error_predicate . to_string ())) . or_default () . push (error . obligation . cause . span) ; } if let ty :: PredicateKind :: Clause (ty :: ClauseKind :: Trait (ty :: TraitPredicate { trait_ref , polarity : ty :: PredicatePolarity :: Positive , .. })) = error_predicate . kind () . skip_binder () { let ty = trait_ref . self_ty () ; if let ty :: Param (_) = ty . kind () { bounds . push ((format ! ("{ty}") , trait_ref . print_trait_sugared () . to_string () , Some (trait_ref . def_id) ,)) ; } } } } InfringingFieldsReason :: Regions (region_errors) => { for error in region_errors { let ty = ty . to_string () ; match error { RegionResolutionError :: ConcreteFailure (origin , a , b) => { let predicate = format ! ("{b}: {a}") ; errors . entry ((ty . clone () , predicate . clone ())) . or_default () . push (origin . span ()) ; if let ty :: RegionKind :: ReEarlyParam (ebr) = b . kind () && ebr . is_named () { bounds . push ((b . to_string () , a . to_string () , None)) ; } } RegionResolutionError :: GenericBoundFailure (origin , a , b) => { let predicate = format ! ("{a}: {b}") ; errors . entry ((ty . clone () , predicate . clone ())) . or_default () . push (origin . span ()) ; if let infer :: region_constraints :: GenericKind :: Param (_) = a { bounds . push ((a . to_string () , b . to_string () , None)) ; } } _ => continue , } } } } } let mut notes = Vec :: new () ; for ((ty , error_predicate) , spans) in errors { let span : MultiSpan = spans . into () ; notes . push (errors :: ImplForTyRequires { span , error_predicate , trait_name : trait_name . clone () , ty , }) ; } let mut err = tcx . dcx () . create_err (errors :: TraitCannotImplForTy { span : impl_span , trait_name , label_spans , notes , }) ; suggest_constraining_type_params (tcx , tcx . hir_get_generics (impl_did) . expect ("impls always have generics") , & mut err , bounds . iter () . map (| (param , constraint , def_id) | (param . as_str () , constraint . as_str () , * def_id)) , None ,) ; err . emit () }
    };
}

infringing_fields_error!()